#!/usr/bin/env python3
"""Turns web/index.html into src/page_html.h so the Vita app can serve it.

Run this again after you edit web/index.html:
    python3 tools/embed_html.py
"""
from pathlib import Path

root = Path(__file__).resolve().parent.parent
data = (root / "web" / "index.html").read_bytes()

lines = []
for i in range(0, len(data), 16):
    chunk = data[i:i + 16]
    lines.append("  " + ", ".join(f"0x{b:02x}" for b in chunk) + ",")

header = (
    "/* Generated by tools/embed_html.py from web/index.html. Do not edit by hand. */\n"
    "#ifndef PAGE_HTML_H\n#define PAGE_HTML_H\n\n"
    f"static const unsigned char PAGE_HTML[] = {{\n" + "\n".join(lines) + "\n};\n"
    f"static const unsigned long PAGE_HTML_LEN = {len(data)};\n\n#endif\n"
)
(root / "src" / "page_html.h").write_text(header)
print(f"Wrote src/page_html.h ({len(data)} bytes of HTML)")
